    {
      "student": "deepseek-v4-flash",
      "shortcut": "Treats the agreements as a tree and uses subtree key counts to identify exactly the edges on paths between key holders",
      "affordance": "“m must be exactly n - 1” together with “exactly one valid sequence”"
    },
    {
      "student": "gpt-oss-120b",
      "shortcut": "Builds a rooted tree using parent information and computes the required path-edge union",
      "affordance": "“for any two corporations ... there is exactly one valid sequence”"
    },
    {
      "student": "glm-5",
      "shortcut": "Constructs adjacency and edge structures for a linear tree traversal/DP over the unique paths",
      "affordance": "“m ... exactly n - 1” and the unique-linking-sequence guarantee"
    }
  ],
  "common_affordance": "The agreements are guaranteed to form a tree, so the required subset is simply the union of the unique paths connecting all key corporations",
